{"path":"ErrorBoundary.tsx","content":"import { Component, ErrorInfo, ReactNode } from "react";

interface Props {
  children: ReactNode;
  fallback?: ReactNode;
  onError?: (error: Error, info: ErrorInfo) => void;
}

interface State {
  error: Error | null;
  errorInfo: ErrorInfo | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null, errorInfo: null };

  static getDerivedStateFromError(error: Error): Partial<State> {
    return { error };
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    this.setState({ errorInfo });
    console.error("[ErrorBoundary] Uncaught error:", error);
    console.error("[ErrorBoundary] Component stack:", errorInfo.componentStack);
    this.props.onError?.(error, errorInfo);
  }

  private handleRetry = () => {
    this.setState({ error: null, errorInfo: null });
  };

  render() {
    const { error, errorInfo } = this.state;

    if (error) {
      if (this.props.fallback) {
        return this.props.fallback;
      }

      return (
        <div role="alert" style={styles.container}>
          <h2 style={styles.heading}>Something went wrong</h2>
          <p style={styles.message}>{error.message}</p>
          {process.env.NODE_ENV !== "production" && errorInfo && (
            <details style={styles.details}>
              <summary style={styles.summary}>Stack trace</summary>
              <pre style={styles.pre}>
                {error.stack}
                {"\n\nComponent stack:"}
                {errorInfo.componentStack}
              </pre>
            </details>
          )}
          <button onClick={this.handleRetry} style={styles.button}>
            Try again
          </button>
        </div>
      );
    }

    return this.props.children;
  }
}

const styles: Record<string, React.CSSProperties> = {
  container: {
    display: "flex",
    flexDirection: "column",
    alignItems: "center",
    justifyContent: "center",
    padding: "2rem",
    margin: "1rem",
    border: "1px solid #f87171",
    borderRadius: "8px",
    backgroundColor: "#fff1f2",
    fontFamily: "sans-serif",
    maxWidth: "600px",
  },
  heading: {
    margin: "0 0 0.5rem",
    color: "#b91c1c",
    fontSize: "1.25rem",
  },
  message: {
    margin: "0 0 1rem",
    color: "#374151",
    textAlign: "center",
  },
  details: {
    width: "100%",
    marginBottom: "1rem",
  },
  summary: {
    cursor: "pointer",
    color: "#6b7280",
    fontSize: "0.875rem",
  },
  pre: {
    overflow: "auto",
    padding: "0.75rem",
    backgroundColor: "#f3f4f6",
    borderRadius: "4px",
    fontSize: "0.75rem",
    color: "#111827",
    whiteSpace: "pre-wrap",
    wordBreak: "break-word",
  },
  button: {
    padding: "0.5rem 1.25rem",
    backgroundColor: "#dc2626",
    color: "#ffffff",
    border: "none",
    borderRadius: "6px",
    cursor: "pointer",
    fontSize: "0.875rem",
    fontWeight: 600,
  },
};
"}

Done. Here's what the component does and how to use it:

**Features**
- `getDerivedStateFromError` captures the error and triggers the fallback render
- `componentDidCatch` logs `error.message`, `error.stack`, and `componentStack` to the console, and calls the optional `onError` prop for external reporting (e.g. Sentry)
- Retry button resets state, causing children to re-mount and attempt a fresh render
- Stack trace `<details>` block is only shown in non-production environments
- Accepts a custom `fallback` prop to override the default UI entirely

**Usage**

```tsx
// Basic
<ErrorBoundary>
  <MyComponent />
</ErrorBoundary>

// With external error reporting
<ErrorBoundary onError={(err, info) => Sentry.captureException(err, { extra: info })}>
  <MyComponent />
</ErrorBoundary>

// With custom fallback UI
<ErrorBoundary fallback={<p>Failed to load. Please refresh.</p>}>
  <MyComponent />
</ErrorBoundary>
```

> **Note:** Error boundaries only catch errors in the React render tree (render, lifecycle methods, constructors). They do not catch errors in event handlers or async code — those need their own `try/catch`.
